class _SupportHomeState extends State<SupportHome> with WindowListener {
  Timer? _timer;
  bool _busy = false;
  String _error = '';

  @override
  void initState() {
    super.initState();
    windowManager.addListener(this);
    _timer = Timer.periodic(const Duration(milliseconds: 500), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    windowManager.removeListener(this);
    super.dispose();
  }

  @override
  void onWindowClose() async {
    await bind.mainSupportSetEnabled(enabled: false);
    // The desktop shell may hide rather than terminate the main process.
    // Closing the app window still ends this password's lifetime.
    await bind.mainSupportRegeneratePassword();
  }

  Future<void> _toggle(bool enabled) async {
    if (_busy) return;
    setState(() { _busy = true; _error = ''; });
    try {
      final error = await bind.mainSupportSetEnabled(enabled: enabled);
      if (mounted) setState(() { _error = error; });
    } catch (_) {
      if (mounted) setState(() { _error = 'Operazione non riuscita. Chiudi il programma per interrompere.'; });
    } finally {
      if (mounted) setState(() { _busy = false; });
    }
  }

  Future<void> _regenerate() async {
    if (_busy) return;
    setState(() { _busy = true; _error = ''; });
    try {
      final error = await bind.mainSupportRegeneratePassword();
      if (mounted) setState(() { _error = error; });
    } catch (_) {
