// Modified distribution. SPDX-License-Identifier: AGPL-3.0-only
import 'package:flutter/material.dart';

String? supportCredentialsError(String id, String password) {
  if (!RegExp(r'^\d+$').hasMatch(id.replaceAll(' ', ''))) {
    return 'Inserisci l’ID numerico del cliente.';
  }
  if (password.isEmpty) return 'Inserisci la password mostrata dal cliente.';
  return null;
}

class SupportCredentials {
  final String id;
  final String password;
  const SupportCredentials(this.id, this.password);
}

bool _credentialsDialogOpen = false;

Future<SupportCredentials?> requestSupportCredentials(
    BuildContext context, String id) async {
  if (_credentialsDialogOpen) return null;
  _credentialsDialogOpen = true;
  try {
    return await showDialog<SupportCredentials>(
      context: context,
      barrierDismissible: false,
      builder: (_) => _SupportCredentialsDialog(id: id),
    );
  } finally {
    _credentialsDialogOpen = false;
  }
}

class _SupportCredentialsDialog extends StatefulWidget {
  final String id;
  const _SupportCredentialsDialog({required this.id});
  @override
  State<_SupportCredentialsDialog> createState() => _SupportCredentialsDialogState();
}

class _SupportCredentialsDialogState extends State<_SupportCredentialsDialog> {
  late final TextEditingController _id;
  final _password = TextEditingController();
  bool _showPassword = false;
  String? _error;
  @override
  void initState() {
    super.initState();
    _id = TextEditingController(text: widget.id);
  }
  @override
  void dispose() {
    _id.dispose();
    _password.dispose();
    super.dispose();
  }
  void _submit() {
    final error = supportCredentialsError(_id.text, _password.text);
    setState(() => _error = error);
    if (error == null) {
      Navigator.of(context).pop(SupportCredentials(
          _id.text.replaceAll(' ', ''), _password.text));
    }
  }
  @override
  Widget build(BuildContext context) => AlertDialog(
    title: const Text('Collegati al cliente'),
    content: SizedBox(width: 360, child: Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        const Text('Inserisci ID e password prima di avviare la connessione.'),
        const SizedBox(height: 16),
        TextField(controller: _id, decoration: const InputDecoration(
            labelText: 'ID cliente', border: OutlineInputBorder())),
        const SizedBox(height: 12),
        TextField(
          controller: _password, autofocus: true, obscureText: !_showPassword,
          autocorrect: false, enableSuggestions: false,
          decoration: InputDecoration(labelText: 'Password cliente',
            border: const OutlineInputBorder(),
            suffixIcon: IconButton(
              tooltip: _showPassword ? 'Nascondi password' : 'Mostra password',
              icon: Icon(_showPassword ? Icons.visibility_off : Icons.visibility),
              onPressed: () => setState(() => _showPassword = !_showPassword))),
          onSubmitted: (_) => _submit()),
        if (_error != null) Padding(padding: const EdgeInsets.only(top: 12),
            child: Text(_error!, style: const TextStyle(color: Colors.red))),
      ])),
    actions: [
      TextButton(onPressed: () => Navigator.of(context).pop(), child: const Text('Annulla')),
      ElevatedButton(onPressed: _submit, child: const Text('Connetti')),
    ],
  );
}

