    await tester.tap(find.text('Connetti'));
    await tester.pumpAndSettle();
    expect(result?.id, '123456');
    expect(result?.password, '  Exact-Pass  ');
    expect(find.byType(AlertDialog), findsNothing);
  });

  testWidgets('Cancellation returns no connection credentials', (tester) async {
    SupportCredentials? result;
    bool completed = false;
    await tester.pumpWidget(MaterialApp(home: Builder(builder: (context) =>
      ElevatedButton(onPressed: () async {
        result = await requestSupportCredentials(context, '123456');
        completed = true;
      }, child: const Text('Apri')))));
    await tester.tap(find.text('Apri'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Annulla'));
    await tester.pumpAndSettle();
