// Modified distribution. SPDX-License-Identifier: AGPL-3.0-only
use hbb_common::protos::message::{ControlKey, KeyboardMode, KeyEvent};

pub fn use_mac_windows_shortcuts(local_mac: bool, custom_operator: bool, windows_peer: bool, manual_swap: bool) -> bool {
    local_mac && custom_operator && windows_peer && !manual_swap
}

/// Translate Mac Command to Windows Ctrl at the final outbound boundary.
/// Real Ctrl, Option/Alt, Shift and ordinary text remain unchanged.
pub fn map_mac_windows_key(event: &mut KeyEvent) {
    if let Some(hbb_common::protos::message::key_event::Union::ControlKey(key)) = event.union {
        let mapped = map_modifier(key.enum_value_or_default());
        event.set_control_key(mapped);
    }
    event.modifiers = event.modifiers.iter()
        .map(|key| hbb_common::protobuf::EnumOrUnknown::new(map_modifier(key.enum_value_or_default())))
        .collect();
    // chr is a Windows scan code only in Map mode; never rewrite Unicode text.
    if event.mode.enum_value_or_default() == KeyboardMode::Map {
        match event.chr() {
            0xe05b => event.set_chr(0x1d),
            0xe05c => event.set_chr(0xe01d),
            _ => {}
        }
    }
}

pub fn map_mac_windows_mouse(event: &mut hbb_common::protos::message::MouseEvent) {
    event.modifiers = event.modifiers.iter()
        .map(|key| hbb_common::protobuf::EnumOrUnknown::new(map_modifier(key.enum_value_or_default())))
        .collect();
}

fn map_modifier(key: ControlKey) -> ControlKey {
    match key {
        ControlKey::Meta => ControlKey::Control,
        ControlKey::RWin => ControlKey::RControl,
        _ => key,
    }
}

