        platform_code: i32,
        position_code: i32,
        lock_modes: i32,
        down_or_up: bool,
    ) {
        if name == "flutter_key" {
            self._handle_key_flutter_simulation(keyboard_mode, platform_code, down_or_up);
        } else {
            self._handle_raw_key_non_flutter_simulation(
                keyboard_mode,
